@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h3># @Channel?.Name</h3>
        <p>@Channel?.Description</p>
    </div>

    <div class="message-list" @ref="messageListRef">
        @if (HasMore)
        {
            <div class="load-more">
                <button @onclick="OnLoadMore" disabled="@IsLoadingMore">
                    @(IsLoadingMore ? "Loading..." : "Load older messages")
                </button>
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadSummary="GetThreadSummary(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="area-input">
        <MessageInput Placeholder="@($"Message #{Channel?.Name}")" OnSubmit="OnSendMessage" />
    </div>
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<MessageArea>? dotNetRef;
    private bool shouldScrollToBottom = true;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Chat/MessageArea.razor.js");
            await jsModule.InvokeVoidAsync("initScrollObserver", messageListRef, dotNetRef);
        }

        if (shouldScrollToBottom && jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            shouldScrollToBottom = false;
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMore && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public void RequestScrollToBottom() => shouldScrollToBottom = true;

    private ThreadSummary? GetThreadSummary(int messageId)
        => ThreadSummaries.GetValueOrDefault(messageId);

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        dotNetRef?.Dispose();
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    background: #fff;
    height: 100%;
    overflow: hidden;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
