let _handler = null;
let _scrollContainer = null;

export function initScrollObserver(scrollContainer, dotNetRef) {
    _scrollContainer = scrollContainer;
    let debouncing = false;
    _handler = () => {
        if (scrollContainer.scrollTop <= 1 && !debouncing) {
            debouncing = true;
            dotNetRef.invokeMethodAsync('OnScrolledToTop').finally(() => {
                setTimeout(() => debouncing = false, 500);
            });
        }
    };
    scrollContainer.addEventListener('scroll', _handler);
}

export function scrollToBottom(scrollContainer) {
    if (scrollContainer) {
        scrollContainer.scrollTop = scrollContainer.scrollHeight;
    }
}

export function dispose() {
    if (_scrollContainer && _handler) {
        _scrollContainer.removeEventListener('scroll', _handler);
        _handler = null;
        _scrollContainer = null;
    }
}

